#include <SPI.h>
#include <MFRC522.h>

// Пины для модуля RC522
#define RST_PIN 9
#define SS_PIN  10

MFRC522 mfrc522(SS_PIN, RST_PIN);

// Пины светодиодов
const byte LED_RED = 8;    // неправильная карта
const byte LED_GREEN = 7;  // правильная карта

// Вставь сюда UID своей «правильной» карты (4 байта)
// Как узнать UID — ниже в инструкции
const byte correctUid[] = {0x01, 0x02, 0x03, 0x04};

void setup() {
  Serial.begin(9600);
  SPI.begin();
  mfrc522.PCD_Init();

  pinMode(LED_RED, OUTPUT);
  pinMode(LED_GREEN, OUTPUT);

  digitalWrite(LED_RED, LOW);
  digitalWrite(LED_GREEN, LOW);

  Serial.println("RFID system ready");
}

void loop() {
  // Если карты нет — ничего не делаем
  if (!mfrc522.PICC_IsNewCardPresent()) return;
  if (!mfrc522.PICC_ReadCardSerial()) return;

  bool isCorrect = true;
  for (byte i = 0; i < 4; i++) {
    if (mfrc522.uid.uidByte[i] != correctUid[i]) {
      isCorrect = false;
      break;
    }
  }

  if (isCorrect) {
    Serial.println("Access granted");
    digitalWrite(LED_RED, LOW);
    digitalWrite(LED_GREEN, HIGH);
  } else {
    Serial.println("Wrong card!");
    digitalWrite(LED_GREEN, LOW);
    digitalWrite(LED_RED, HIGH);
  }

  delay(1000); // Пауза, чтобы не срабатывало много раз подряд
  mfrc522.PICC_HaltA();
}
